def migrate(conn):
    row = conn.execute("SELECT version FROM meta").fetchone()
    if row is None or row[0] not in (1, 2):
        raise ValueError("unsupported schema version")
    if row[0] == 2:
        return

    conn.execute("BEGIN IMMEDIATE")
    try:
        conn.execute("CREATE TABLE bindings (id TEXT PRIMARY KEY, policy TEXT NOT NULL)")
        conn.execute("UPDATE meta SET version = 2")
        conn.execute("COMMIT")
    except BaseException:
        conn.execute("ROLLBACK")
        raise
